#!/usr/bin/env python3
from pathlib import Path
import json, re

ROOT=Path(__file__).resolve().parents[1]

TR_PRODUCT='AI Görünürlük Yol Haritası'
EN_PRODUCT='AI Search Visibility Roadmap'
PRICE='$99'
SUPPORT='contact@htmlandhtml.com'


def write(path:Path,text:str):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(text.strip()+"\n",encoding='utf-8')


def normalize_public_sources():
    for p in ROOT.rglob('*.html'):
        if any(x in p.parts for x in ('.git','node_modules','functions','functions-firebase')): continue
        s=p.read_text(encoding='utf-8')
        tr='lang="tr"' in s or p.parts[:1]==('tr',)
        s=s.replace('$149','$99').replace('149 USD','99 USD').replace('price": "149"','price": "99"')
        s=s.replace('Full Site Fix Mandate',TR_PRODUCT if tr else EN_PRODUCT)
        s=s.replace('Full Website Diagnosis','AI Visibility Evidence Report')
        if tr:
            for a,b in [('uygulama reçetesi','uygulama yol haritası'),('Uygulama reçetesi','Uygulama yol haritası'),('reçeteyi','yol haritasını'),('reçetesi','yol haritası'),('reçete','yol haritası')]: s=re.sub(a,b,s,flags=re.I)
        p.write_text(s,encoding='utf-8')


def legal_shell(lang,title,description,h1,body,canonical,alternate,refund_href):
    tr=lang=='tr'
    home='/tr/' if tr else '/en/'
    pricing='/tr/fiyatlandirma/' if tr else '/en/pricing/'
