    contact='/tr/iletisim/' if tr else '/en/contact/'
    about='/tr/hakkimizda/' if tr else '/en/about/'
    labels=('Fiyat','Gizlilik','Koşullar','İade','İletişim') if tr else ('Pricing','Privacy','Terms','Refunds','Contact')
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="{'en' if tr else 'tr'}" href="{alternate}"><link rel="describedby" href="https://htmlandhtml.com/llms.txt"><link rel="stylesheet" href="/assets/css/authority.css"><link rel="stylesheet" href="/assets/css/enterprise-system.css?v=1"><script src="/assets/js/theme.js"></script></head><body><header class="topbar"><div class="topbar-shell"><a class="brand" href="{home}" aria-label="HTML&amp;HTML"><img class="brand-logo" src="/assets/logo.png" alt="HTML&amp;HTML" width="144" height="22"></a><nav><a href="{about}">{'Hakkımızda' if tr else 'About'}</a><a href="{pricing}">{labels[0]}</a><a href="{privacy}">{labels[1]}</a><a href="{terms}">{labels[2]}</a><a href="{refund_href}">{labels[3]}</a><a href="{contact}">{labels[4]}</a></nav></div></header><main><section class="authority-hero" style="max-width:var(--shell-max);margin:0 auto;padding:72px 28px 48px"><div class="kicker"><span></span><b>{'SAAS / KURUMSAL' if tr else 'SAAS / COMPANY'}</b></div><h1>{h1}</h1><p>{description}</p></section><section class="section" style="max-width:var(--shell-max);margin:0 auto"><div class="legal-body" style="max-width:900px;font-size:17px;line-height:1.75">{body}</div></section></main><footer><div class="footer-bottom" style="max-width:var(--shell-max);margin:auto;padding:28px"><span>© 2026 HTML&amp;HTML</span><span><a href="{terms}">{labels[2]}</a> · <a href="{privacy}">{labels[1]}</a> · <a href="{refund_href}">{labels[3]}</a> · <a href="{contact}">{labels[4]}</a></span></div></footer></body></html>'''


