def patch_pricing_and_sitemap():
    for rel,tr in [('tr/fiyatlandirma/index.html',True),('en/pricing/index.html',False)]:
        p=ROOT/rel
        if not p.exists(): continue
        s=p.read_text(encoding='utf-8')
        if 'data-paddle-saas-readiness' not in s:
            block=('''<section class="px-section" data-paddle-saas-readiness="true"><div class="px-section-head"><span class="eyebrow">SAAS ÜRÜN SINIRI</span><h2>Danışmanlık değil, otomatik yazılım teslimi.</h2><p>$99 tek seferlik dijital ürün; ödeme doğrulandıktan sonra hedef domainin yeniden taranmasıyla otomatik oluşturulur. Abonelik, manuel danışmanlık veya insan eliyle hazırlanmış özel rapor içermez.</p><p><a href="/tr/kullanim-kosullari/">Kullanım Koşulları</a> · <a href="/tr/gizlilik/">Gizlilik</a> · <a href="/tr/iade-politikasi/">İade Politikası</a> · <a href="/tr/iletisim/">İletişim</a></p></div></section>''' if tr else '''<section class="px-section" data-paddle-saas-readiness="true"><div class="px-section-head"><span class="eyebrow">SAAS PRODUCT BOUNDARY</span><h2>Automated software, not consulting.</h2><p>The $99 one-time digital product is generated automatically by re-scanning the target domain after verified payment. No subscription, manual consulting or consultant-written custom report is included.</p><p><a href="/en/terms/">Terms</a> · <a href="/en/privacy/">Privacy</a> · <a href="/en/refund/">Refund Policy</a> · <a href="/en/contact/">Contact</a></p></div></section>''')
            s=s.replace('</main>',block+'</main>',1)
        p.write_text(s,encoding='utf-8')
    sm=ROOT/'sitemap.xml'
    if sm.exists():
        s=sm.read_text(encoding='utf-8')
        urls=['https://htmlandhtml.com/tr/iade-politikasi/','https://htmlandhtml.com/en/refund/']
        add=''.join(f'<url><loc>{u}</loc><changefreq>monthly</changefreq><priority>0.5</priority></url>' for u in urls if u not in s)
        if add: s=s.replace('</urlset>',add+'</urlset>')
        sm.write_text(s,encoding='utf-8')


def patch_news_hardening():
    p=ROOT/'scripts/update_llms_news.py'
    s=p.read_text(encoding='utf-8')
    if "REQUIRE_KEY='--require-editorial-key' in sys.argv" not in s:
        s=s.replace("API_KEY=os.getenv('NEWS_EDITORIAL_OPENAI_KEY','').strip()", "API_KEY=os.getenv('NEWS_EDITORIAL_OPENAI_KEY','').strip()\nREQUIRE_KEY='--require-editorial-key' in sys.argv")
        s=s.replace("if not API_KEY:\n        print('LLMS_NEWS_SAFE_NOOP: NEWS_EDITORIAL_OPENAI_KEY is not configured; discovery may run but no automatic content will be published.')\n        return 0", "if not API_KEY:\n        msg='NEWS_EDITORIAL_OPENAI_KEY is not configured; scheduled publication cannot run.'\n        if REQUIRE_KEY: raise SystemExit('LLMS_NEWS_CONFIG_FAIL: '+msg)\n        print('LLMS_NEWS_SAFE_NOOP: '+msg)\n        return 0")
    p.write_text(s,encoding='utf-8')
    wf=ROOT/'.github/workflows/llms-news.yml'
    s=wf.read_text(encoding='utf-8')
    s=s.replace('run: python3 scripts/update_llms_news.py','run: python3 scripts/update_llms_news.py --require-editorial-key')
    s=s.replace("      - name: Materialize bilingual news pages and machine-readable discovery\n        if: steps.editorial.outputs.changed == 'true'\n        run: python3 scripts/build_llms_news.py\n      - name: Validate news editorial and SEO contract\n        if: steps.editorial.outputs.changed == 'true'\n        run: node tests/integrity/llms-news.test.mjs", "      - name: Materialize bilingual news pages and machine-readable discovery\n        run: python3 scripts/build_llms_news.py\n      - name: Validate news editorial and SEO contract\n        run: node tests/integrity/llms-news.test.mjs")
    wf.write_text(s,encoding='utf-8')


def patch_package():
    p=ROOT/'package.json'; d=json.loads(p.read_text())
    d['scripts']['test:source']='python3 scripts/assert_source_contract.py'
    d['scripts']['test:paddle']='node tests/integrity/paddle-readiness.test.mjs'
    d['scripts']['test']='npm run test:source && npm run build:commercial && npm run test:python && npm run test:integrity && npm run test:paddle && npm run test:client'
    # Keep readiness generation deterministic before the rest of the commercial materialization chain.
    if not d['scripts']['build:commercial'].startswith('python3 scripts/prepare_paddle_saas.py && '):
        d['scripts']['build:commercial']='python3 scripts/prepare_paddle_saas.py && '+d['scripts']['build:commercial']
    if 'scripts/prepare_paddle_saas.py' not in d['scripts']['test:python']:
        d['scripts']['test:python']=d['scripts']['test:python'].replace('python3 -m py_compile ','python3 -m py_compile scripts/prepare_paddle_saas.py scripts/assert_source_contract.py ')
    p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')


